/** Where refined product lands. */
export const StoreKind = z.enum([
  "qdrant",       // vector collection, cosine
  "faiss-pack",   // signed terrain pack, L2-to-centroid (Zone 2 kernel)
  "vault-index",  // vault/index.json — SimHash Hamming index
