  queryId: string;
  class: QueryClass;
  outcome: Outcome;
  bestScore?: number;
  latencyMs?: number;
  answer?: string;
  evidenceIds?: string[];
}

export interface Metrics {
  adapterName: string;
  threshold?: number;
  counts: Record<Outcome, number>;
