GUTENBERG_YEARS = {
    # Publication years for known Gutenberg works in corpus
    'blackstone':        1765,
    'magna carta':       1215,
    'visigothic':        1910,  # Forum Judicum translation
    'aethelbert':        1840,  # Our Legal Heritage translation
