  return MANIFEST.pipelines
    .filter((p) => (p.notes ?? "").includes("AMBIGUITY") || (p.silence.calibration.note ?? "").includes("CONFIRM"))
    .map((p) => ({ id: p.id, note: p.notes }));
}

