/**
 * WHITE-GLOVE AGENT HUSK: LFU Shard Cache
 * 
 * Bounded-memory cache for Spectral Shards using Least-Frequently-Used
 * eviction with LRU tie-breaking. Keeps hot knowledge in RAM while
 * staying within the 3.05GB budget of the CPU-bound failover.
 * 
 * For M < 1000 active shards, sorted-array eviction is sufficient.
 * Upgrade to min-heap only if M exceeds 10,000.
 * 
 * Based on: Mentor Directive #2 — O(logM) LFU Min-Heap Gating
 */

export interface CachedShard {
  /** Shard identifier (e.g., "shard_0001") */
  id: string;
  /** Raw text content of the shard */
  content: string;
  /** Source document identifier */
  source: string;
  /** SimHash-128 signature (if computed) */
  signature?: bigint;
  /** ℓ₂-normalized embedding vector (if computed) */
  embedding?: Float64Array;
  /** Metadata from the shard JSON */
  metadata?: Record<string, unknown>;
}

interface CacheEntry {
  shard: CachedShard;
  frequency: number;
  lastAccessed: number; // monotonic counter for LRU tie-breaking
}

export class ShardCache {
  private readonly maxSize: number;
  private readonly cache: Map<string, CacheEntry> = new Map();
  private accessCounter: number = 0;

  /** Eviction callback — notifies callers when a shard is dropped */
  public onEvict?: (shard: CachedShard) => void;

  /**
   * @param maxSize - Maximum number of shards to hold in memory.
   *   Calibrate based on average shard size and available RAM.
   *   For 3.05GB environment with ~2KB avg shard: maxSize ≈ 500-1000.
   */
  constructor(maxSize: number = 500) {
    if (maxSize < 1) throw new Error("Cache maxSize must be >= 1");
    this.maxSize = maxSize;
  }

  /**
   * Retrieve a shard from cache. Increments frequency counter.
   * Returns undefined if not cached (caller must load from disk).
   */
  get(shardId: string): CachedShard | undefined {
    const entry = this.cache.get(shardId);
    if (!entry) return undefined;

    entry.frequency++;
    entry.lastAccessed = ++this.accessCounter;
    return entry.shard;
  }

  /**
   * Insert a shard into cache. Evicts if at capacity.
   * If the shard already exists, updates content and bumps frequency.
   */
  put(shard: CachedShard): void {
    const existing = this.cache.get(shard.id);

    if (existing) {
      existing.shard = shard;
      existing.frequency++;
      existing.lastAccessed = ++this.accessCounter;
      return;
    }

    // Evict if at capacity
    if (this.cache.size >= this.maxSize) {
      this.evictOne();
    }

    this.cache.set(shard.id, {
      shard,
      frequency: 1,
      lastAccessed: ++this.accessCounter
    });
  }

  /**
   * Evict the least-frequently-used shard.
   * On frequency tie, evict the least-recently-accessed (LRU tie-break).
   */
  private evictOne(): void {
    let victim: string | null = null;
    let victimFreq = Infinity;
    let victimAccess = Infinity;

    for (const [id, entry] of this.cache) {
      if (
        entry.frequency < victimFreq ||
        (entry.frequency === victimFreq && entry.lastAccessed < victimAccess)
      ) {
        victim = id;
        victimFreq = entry.frequency;
        victimAccess = entry.lastAccessed;
      }
    }

    if (victim) {
      const evicted = this.cache.get(victim);
      this.cache.delete(victim);
      if (evicted && this.onEvict) {
        this.onEvict(evicted.shard);
      }
    }
  }

---

  /**
   * Build the in-memory SimHash index from all shards on disk.
   * Called once at startup or during the Dream cycle.
   */
  async saveIndex(filePath: string) {
    const data = {
      index: this.index.map((entry) => ({
        shardId: entry.shardId,
        title: entry.title,
        signatureHex: entry.signature.toString(16),
        source: entry.source,
        contentPreview: entry.contentPreview,
        frequency: entry.frequency
      })),
      indexedCount: this.indexedCount
    };
    await fs.promises.writeFile(filePath, JSON.stringify(data));
    console.log(`💾 [HUSK] Index persisted to ${filePath}`);
  }

  async loadIndex(filePath: string) {
    if (!fs.existsSync(filePath)) return false;
    const raw = await fs.promises.readFile(filePath, 'utf-8');
    const data = JSON.parse(raw);
    this.index.length = 0;
    if (Array.isArray(data.index)) {
      for (const row of data.index) {
        this.index.push({
          shardId: row.shardId,
          title: row.title || "Untitled",
          signature: BigInt(`0x${row.signatureHex}`),
          source: row.source,
          contentPreview: row.contentPreview || "",
          frequency: row.frequency || 0
        });
      }
    }
    this.indexedCount = this.index.length;
    this.initialized = true;
    this.rebalanceHotBuffer();
    console.log(`🔋 [HUSK] Index restored: ${this.indexedCount} landmarks`);
    return true;
  }

  /**
   * Build the in-memory SimHash index from all shards on disk.
   * Hardened for memory safety and large-scale datasets.
   */
  async buildIndex(limit?: number): Promise<void> {
    const startMs = Date.now();
    this.index.length = 0;
    const MAX_FILE_SIZE = 1024 * 1024; // 1MB safety cap per shard
    const BATCH_SIZE = 100;

    if (!fs.existsSync(this.config.shardDir)) {
      console.warn(`⚠️ [ORCHESTRATOR] Shard directory not found: ${this.config.shardDir}`);
      return;
    }

    const files = fs.readdirSync(this.config.shardDir)
      .filter((f: string) => f.endsWith(".json"))
      .sort();

    console.log(`💎 [ORCHESTRATOR] Building index for ${files.length} shards...`);

    let processed = 0;
    let skipped = 0;

    for (let i = 0; i < files.length; i++) {
      if (limit && processed >= limit) break;

      const file = files[i];
      const filePath = path.join(this.config.shardDir, file);

      try {
        const stats = fs.statSync(filePath);
        if (stats.size > MAX_FILE_SIZE) {
          console.warn(`⚠️ [ORCHESTRATOR] Skipping oversized shard (${(stats.size / 1024).toFixed(1)}KB): ${file}`);
          skipped++;
          continue;
        }

        const raw = fs.readFileSync(filePath, "utf-8");
        const shard = JSON.parse(raw);

        // Required fields check
        if (!shard.content) {
          console.warn(`⚠️ [ORCHESTRATOR] Skipping invalid shard (missing content): ${file}`);
          skipped++;
          continue;
        }

        const signature = this.guard.simHash128FromText(shard.content, "corpus");

        this.index.push({
          shardId: shard.id || shard.shardId || file.replace(".json", ""),
          title: shard.title || "Untitled",
          signature,
          source: shard.source || "unknown",
          contentPreview: shard.content.slice(0, 100).replace(/\n/g, " "),
          frequency: 0
        });

        processed++;

        // Every BATCH_SIZE files, yield to the event loop to allow GC
        if (processed % BATCH_SIZE === 0) {
          await new Promise(resolve => setImmediate(resolve));
        }

      } catch (err) {
        console.error(`❌ [ORCHESTRATOR] Error processing shard ${file}:`, err);
        skipped++;
      }
    }

    this.initialized = true;
    this.indexedCount = this.index.length;
    this.rebalanceHotBuffer();

